@js:
eval(String(source.variableComment));

var Csrf_token = cookie.getKey(source.getKey(), '__csrf');
var outplayList = source.getLoginInfoMap() ? source.getLoginInfoMap().get("导入歌单：") : null;
var match = String(outplayList).match(/playlist\?id=(\d+)/);
var songlist = [];

function fetchData(param, url) {
    var params = encryption(encryption(JSON.stringify(param), '0CoJUm6Qyw8W8jud'), i_data);
    var encSecKey = encSecKeyEncryption(i_data, encSecKeyParameterOne, encSecKeyParameterTwo);
    var body = `params=${params}&encSecKey=${encSecKey}`;
    var headers = {
        'content-type': 'application/x-www-form-urlencoded',
        'referer': 'https://music.163.com/'
    };
    var option = {
        "method": "POST",
        "body": body,
        "headers": headers
    };
    var postUrl = url + "," + JSON.stringify(option);
    var resp = JSON.parse(java.ajax(postUrl));
    return resp;
}

if (baseUrl.includes("limit=35")) {
	// 分类歌单
	var list = java.getElements('#m-pl-container li');
	for (var i = 0; i < list.length; i++) {
		var item = list[i];
		var name = item.select('p.dec a').text();
		var author = item.select('a.s-fc3').text();
		var kind = item.select('span.nb').text();
		var cover = String(item.select('img.j-flag').attr('src')).split("?")[0];
		var intro = item.select('p.dec a').text();
                var url = item.select('p.dec a').attr('href');
		songlist.push({
			'name': name,
			'author': author,
			'kind': kind,
			'intro': intro,
			'cover': cover,
			'url': url
		});
	}
} else if (baseUrl.endsWith("discover/toplist")) {
	// 特色榜
	var param = {};
	var resp = fetchData(param, "https://music.163.com/weapi/toplist/detail");
	if (resp.code == 200) {
		var songList = resp.list;
		for (var i = 0; i < 4; i++) {
			songlist.push({
				'name': songList[i].name,
				'author': "云音乐官方榜单",
				'kind': songList[i].updateFrequency,
				'intro': songList[i].description,
				'cover': songList[i].coverImgUrl,
				'url': `/discover/toplist?id=${songList[i].id}`
			});
		}
	}
} else if (baseUrl.includes("toplist?id=")) {
	// 媒体榜
	var param = {};
	var resp = fetchData(param, "https://music.163.com/weapi/toplist/detail");
	if (resp.code == 200) {
		var songList = resp.list;
		for (var i = 4; i < songList.length; i++) {
			songlist.push({
				'name': songList[i].name,
				'author': "云音乐官方榜单",
				'kind': songList[i].updateFrequency,
				'intro': songList[i].description,
				'cover': songList[i].coverImgUrl,
				'url': `/discover/toplist?id=${songList[i].id}`
			});
		}
	}
} else if (baseUrl.includes("user/home")) {

var userInfo = JSON.parse(java.get("userinfo"));
var nickname = userInfo.nickname;
var userId = userInfo.userId;

	// 我的创建
	var param = { uid: userId, wordwrap: '7', offset: '0', total: 'true', limit: '100', csrf_token: Csrf_token };
	var resp = fetchData(param, `https://music.163.com/weapi/user/playlist?csrf_token=${Csrf_token}`);
	if (resp.code == 200) {
		var songList = resp.playlist;
		for (var i = 0; i < songList.length; i++) {
			if (songList[i].creator.userId == userId) {
				songlist.push({
					'name': songList[i].name,
					'author': songList[i].creator.nickname,
					'kind': songList[i].tags,
					'intro': songList[i].description?songList[i].description:' ｡:.ﾟヽ(｡◕‿◕｡)ﾉﾟ.:｡+ﾟ',
					'cover': songList[i].coverImgUrl,
					'url': `/playlist?id=${songList[i].id}`
				});
			} else {
				break;
			}
		}
	}
} else if (baseUrl.includes("user/event")) {

var userInfo = JSON.parse(java.get("userinfo"));
var nickname = userInfo.nickname;
var userId = userInfo.userId;

	// 我的收藏
	var param = { uid: userId, wordwrap: '7', offset: '0', total: 'true', limit: '100', csrf_token: Csrf_token };
	var resp = fetchData(param, `https://music.163.com/weapi/user/playlist?csrf_token=${Csrf_token}`);
	if (resp.code == 200) {
		var songList = resp.playlist;
		for (var i = 0; i < songList.length; i++) {
			if (songList[i].creator.userId != userId) {
				songlist.push({
					'name': songList[i].name,
					'author': songList[i].creator.nickname,
					'kind': songList[i].tags,
					'intro': songList[i].description,
					'cover': songList[i].coverImgUrl,
					'url': `/playlist?id=${songList[i].id}`
				});
			}
		}
	}
} else if (baseUrl.endsWith("/discover")) {
	// 个性推荐
	var param = { limit: 30, total: true, n: 1000 };
	var resp = fetchData(param, "https://music.163.com/weapi/personalized/playlist");
	if (resp.code == 200) {
		var songList = resp.result;
		for (var i = 0; i < songList.length; i++) {
			songlist.push({
				'name': songList[i].name,
				'author': "云音乐官方",
				'kind': ["个性推荐"],
				'intro': songList[i].name,
				'cover': songList[i].picUrl,
				'url': `/playlist?id=${songList[i].id}`
			});
		}
	}
} else if (baseUrl.includes("songs/rank")) {

var userInfo = JSON.parse(java.get("userinfo"));
var nickname = userInfo.nickname;
var userId = userInfo.userId;

	// 听歌排行
	songlist.push({
		'name': "听歌排行",
		'author': nickname,
		'kind': ["听歌排行"],
		'intro': " ｡:.ﾟヽ(｡◕‿◕｡)ﾉﾟ.:｡+ﾟ",
		'cover': userInfo.avatarUrl,
		'url': baseUrl
	});
} else if (match && baseUrl.includes("limit=1")) {
	// 外部歌单
	var playlistUrl = 'https://music.163.com/playlist?id=' + match[1];
	var html = java.ajax(playlistUrl);
	var doc = org.jsoup.Jsoup.parse(html);
	var list = doc.select('#m-playlist');
	var name = list.select('.tit').text();
	var author = list.select('span.name a').text();
	var kind = list.select('strong.s-fc6').text();
	var cover = String(list.select('img.j-img').attr('data-src')).split("?")[0];
	var intro = list.select('p#album-desc-more').text();
	var url = playlistUrl;
	songlist.push({
		'name': name,
		'author': author,
		'kind': [kind, "外部歌单"],
		'intro': intro,
		'cover': cover,
		'url': url
	});
} else {
	java.toast("歌单格式错误或未导入歌单");
}

result = songlist;

